import{c as e,Q as t,j as a,m as o}from"./chunks/framework.BPKcPtvA.js";const _=JSON.parse('{"title":"RO3 开放事前预约 领地争霸战抢鲜体验赛花絮","description":"RO3 正式开放事前预约，线下领地争霸战 50 名玩家激战巅峰对决","frontmatter":{"title":"RO3 开放事前预约 领地争霸战抢鲜体验赛花絮","description":"RO3 正式开放事前预约，线下领地争霸战 50 名玩家激战巅峰对决"},"headers":[],"relativePath":"news/preorder-territory-202511.md","filePath":"news/preorder-territory-202511.md","lastUpdated":1779114110000}'),l={name:"news/preorder-territory-202511.md"};function i(n,r,s,p,d,c){return t(),a("div",null,[...r[0]||(r[0]=[o('<h1 id="事前预约开放-领地争霸战抢鲜体验赛" tabindex="-1">事前预约开放！领地争霸战抢鲜体验赛 <a class="header-anchor" href="#事前预约开放-领地争霸战抢鲜体验赛" aria-label="Permalink to &quot;事前预约开放！领地争霸战抢鲜体验赛&quot;">​</a></h1><p>日期：2025-11-25</p><p>RO3 于今日起正式开放事前预约，同时官方释出「领地争霸战抢鲜体验赛」花絮报导，现场集结 50 位玩家亲身参与攻城玩法「巅峰对决」。</p><h2 id="巅峰对决核心玩法" tabindex="-1">巅峰对决核心玩法 <a class="header-anchor" href="#巅峰对决核心玩法" aria-label="Permalink to &quot;巅峰对决核心玩法&quot;">​</a></h2><p>全新攻城玩法「巅峰对决」是领地争霸战的最終决战，两大公会展开大规模对抗，分为三个阶段：</p><ol><li><strong>突破城牆防线</strong> — 运用攻城车、云梯攻破外城</li><li><strong>内城混战</strong> — 进入城内展开激烈巷战</li><li><strong>争夺华麗金属</strong> — 围绕王城核心目标决胜</li></ol><p>战场中可灵活运用攻城车、云梯、砲台、巨型机甲与指挥技能等多种资源。</p><h2 id="现场赛事实况" tabindex="-1">现场赛事实况 <a class="header-anchor" href="#现场赛事实况" aria-label="Permalink to &quot;现场赛事实况&quot;">​</a></h2><p>四支公会（皇家骑士团、대한민국、LEGENDS、GARUDA）参与跨区友谊赛：</p><ul><li><strong>首战</strong>：皇家骑士团仅 5 分钟击破「华麗金属」夺胜</li><li><strong>次战</strong>：刺客小队绕道潜入水晶房，施放「紧急呼叫」全员集火再下一城</li><li><strong>最终战</strong>：虽未攻破 LEGENDS 防线，但精采表现赢得全场喝采</li></ul><h2 id="事前预约已开放" tabindex="-1">事前预约已开放 <a class="header-anchor" href="#事前预约已开放" aria-label="Permalink to &quot;事前预约已开放&quot;">​</a></h2><p>玩家可至官网进行预约，锁定后续测试计划与最新消息。</p><p><small>消息来源：巴哈姆特 GNN 整理报导</small></p>',13)])])}const m=e(l,[["render",i]]);export{_ as __pageData,m as default};
